import * as dotenv from 'dotenv';

/**
 *
 */
export function loadEnvironment(): void {
  dotenv.config();
}

/**
 *
 */
export async function startApp(): Promise<void> {
  const { NestFactory } = await import('@nestjs/core');
  const express = await import('express');
  const { AppModule } = await import('../app.module');

  const app = await NestFactory.create(AppModule, {
    rawBody: true,
  });

  app.use(express.json({ type: 'application/json' }));
  app.use(express.json({ type: 'application/cloudevents+json' }));
  app.enableShutdownHooks();

  await app.listen(3000);
}

interface TelemetryConfig {
  enableAzureSdkInstrumentation?: boolean;
  enableTelemetry: boolean;
  enableTraceBasedSamplingForLogs?: boolean;
  enableRedisInstrumentation?: boolean;
  enablePerformanceCounters?: boolean;
  enableLiveMetrics?: boolean;
  enableMetrics?: boolean;
  connectionString: string;
  serviceName: string;
  samplingRatio?: number;
  hostName?: string;
}

/**
 * Gets telemetry configuration from environment variables.
 * @returns The telemetry configuration object.
 */
function getTelemetryConfigFromEnvironment(): TelemetryConfig {
  return {
    connectionString: process.env.APPLICATIONINSIGHTS_CONNECTION_STRING ?? '',
    enableAzureSdkInstrumentation:
      process.env.ENABLE_AZURE_SDK_INSTRUMENTATION === 'true',
    enableLiveMetrics: process.env.ENABLE_LIVE_METRICS === 'true',
    enableMetrics: process.env.ENABLE_METRICS === 'true',
    enablePerformanceCounters:
      process.env.ENABLE_PERFORMANCE_COUNTERS === 'true',
    enableRedisInstrumentation:
      process.env.ENABLE_REDIS_INSTRUMENTATION === 'true',
    enableTelemetry: process.env.ENABLE_APP_INSIGHTS_TELEMETRY === 'true',
    enableTraceBasedSamplingForLogs:
      process.env.ENABLE_TRACE_BASED_SAMPLING_FOR_LOGS === 'true',
    hostName: process.env.HOSTNAME,
    samplingRatio: process.env.TELEMETRY_SAMPLING_RATIO
      ? Number(process.env.TELEMETRY_SAMPLING_RATIO)
      : undefined,
    serviceName: process.env.SERVICE_NAME ?? '',
  };
}

/**
 * Initializes telemetry based on environment configuration.
 * @returns Promise that resolves when telemetry is initialized.
 */
export async function initTelemetry(): Promise<void> {
  const config = getTelemetryConfigFromEnvironment();

  const { initializeTelemetry, telemetryMetrics } = await import(
    '@mesx/common-lib/telemetry'
  );

  const result = initializeTelemetry(config);
  if (result.success && config.enableTelemetry) {
    telemetryMetrics.initialize({
      serviceName: config.serviceName,
      hostName: config.hostName,
    });
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '../logger/app-logger';
import { getPendingMessagesCount } from '@/helpers/statistics/pending-message-stats';

interface LogTrace {
  details?: Record<string, unknown>;
  logType: string;
  operationName: string;
  runtime: number;
  srcLocation: string;
  waitingMsgCount: number;
}

/**
 * Execution function and log runtime
 * @param logger Application logger
 * @param operation Function to execute
 * @param operationInfo Function properties
 * @param operationInfo.name Function name
 * @param operationInfo.srcLocation Caller code source location
 * @param context Job Log Context
 * @param details (optional)
 * @param startTime starting time
 * @returns function output
 */
export async function execAndLog<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  operationInfo: {
    name: string;
    srcLocation: string;
  },
  details?: Record<string, unknown>,
  startTime = Date.now(),
): Promise<T> {
  const result = await operation();
  const logTrace: LogTrace = {
    details,
    logType: 'Exec trace',
    operationName: operationInfo.name,
    runtime: Date.now() - startTime,
    srcLocation: operationInfo.srcLocation,
    waitingMsgCount: getPendingMessagesCount(),
  };
  logger.debug(JSON.stringify(logTrace), context);
  return result;
}

