import { ReworkList } from '@/modules/rework-list/entities/rework-list.entity';
import { ScrapList } from '@/modules/scrap-list/scrap-list.entity';

export interface Mapping {
  /**
   * Source table in SAP DMC
   */
  source: string;

  /**
   * Target table in MESX
   */
  destination: string;

  /**
   * Key fields source and associated column in target structure
   */
  keys: Array<KeyMapping>;

  /**
   * Column mapping
   */
  columnMappings: Array<ColumnMapping>;
}

export interface KeyMapping {
  /**
   * Source field
   */
  keySource: string;

  /**
   * Target field
   */
  keyDestination: string;
}

export interface ColumnMapping {
  /**
   * Source field
   */
  columnSource: string;

  /**
   * Target field
   */
  columnDestination: string;
  /**
   * Type field
   */
  type?: string;
  /**
   * AllowEmpty field
   */
  allowEmpty?: boolean;
}

export type MappedOutput = ScrapList | ReworkList;

