import { DaprClient, CommunicationProtocolEnum } from '@dapr/dapr';
import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DowntimeTicketMessage } from './interface/publish-downtime-ticket.interface';
import { AppLogger } from '@/common/logger/app-logger';
