import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ReworkList } from './entities/rework-list.entity';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class ReworkListService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: ReworkListService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(ReworkList)
    private readonly reworkListRepository: Repository<ReworkList>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('reworkList.c')
  private async create(payload: ReworkList): Promise<void> {
    const context = ReworkListService.createLogContext(
      'create',
      payload?.plant,
      String(payload?.id),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty ${payload}`, context);
    const operationInfo = {
      name: 'Create Rework List (SQL)',
      srcLocation: 'reworkList.c',
    };
    const startTime = Date.now();
    try {
      const { ...reworkList } = payload;
      await execAndLog(
        this.customLogger,
        context,
        () => this.reworkListRepository.save(reworkList),
        operationInfo,
        { reworkList },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'rework-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'rework-list',
      );
      this.customLogger.debug(
        `Rework List ${reworkList.id} is inserted`,
        context,
      );
    } catch (error) {
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'rework-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'rework-list-create',
      );
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
        error,
      );
    }
    return undefined;
  }

  @OnEvent('reworkList.u')
  private async updateById(payload: ReworkList): Promise<void> {
    const context = ReworkListService.createLogContext(
      'updateById',
      payload?.plant,
      String(payload?.id),
    );
    const { id } = payload;
    const operationInfo = {
      name: 'Update Rework List by id (SQL)',
      srcLocation: 'reworkList.u',
    };

    if (!payload)
      return this.customLogger.error(
        `payload is empty ${JSON.stringify(payload)}`,
        context,
      );

    const startTime = Date.now();
    try {
      operationInfo.name = 'Read Rework List (SQL)';
      const reworkList = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.reworkListRepository.findOne({
            select: [
              'id',
              'plant',
              'creationDate',
              'materialId',
              'quantity',
              'resourceId',
              'workCenterId',
              'reversed',
            ],
            where: { id },
          }),
        operationInfo,
      );
      if (!reworkList) {
        await this.create(payload);
        return undefined;
      }

      const { ...reworkListUpdated } = payload;
      operationInfo.name = 'Update Rework List (SQL)';
      await execAndLog(
        this.customLogger,
        context,
        () => this.reworkListRepository.update({ id }, reworkListUpdated),
        operationInfo,
        { reworkListUpdated },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'rework-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'rework-list',
      );
    } catch (error) {
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'rework-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'rework-list',
      );
      this.customLogger.error(
        `Error updating Rework List: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('reworkList.r')
  public async readSnapshot(payload: ReworkList): Promise<void> {
    const context = ReworkListService.createLogContext(
      'readSnapshot',
      payload?.plant,
      String(payload?.id),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    const operationInfo = {
      name: 'reworkList readSnapshot (SQL)',
      srcLocation: 'reworkList.r readSnapshot',
    };
    const startTime = Date.now();
    try {
      const { id, plant, ...reworkListUpdated } = payload;
      const transactionPromise = this.reworkListRepository.manager.transaction(
        async (transactionalEntityManager) => {
          let reworkList = await transactionalEntityManager.findOne(
            ReworkList,
            {
              where: { id, plant },
            },
          );
          if (reworkList) {
            Object.assign(reworkList, reworkListUpdated);
          } else {
            reworkList = transactionalEntityManager.create(ReworkList, {
              id,
              plant,
              ...reworkListUpdated,
            });
          }
          await transactionalEntityManager.save(reworkList);
        },
      );
      await execAndLog(
        this.customLogger,
        context,
        () => transactionPromise,
        operationInfo,
        {
          reworkListUpdated,
        },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'rework-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'rework-list',
      );
    } catch (error) {
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'rework-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'rework-list',
      );
      this.customLogger.error(
        `Error updating Rework List: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
}

