    private readonly scrapListRepository: Repository<ScrapList>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('scrapList.c')
  private async create(payload: ScrapList): Promise<void> {
    const context = ScrapListService.createLogContext(
      'create',
      payload?.plant,
      payload?.scrapListId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const startTime = Date.now();
    try {
      const { ...scrapListData } = payload;
      scrapListData.creationDate = new Date(payload.creationDate);
      await this.scrapListRepository.save(scrapListData);
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'scrap-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'scrap-list',
      );
      this.customLogger.debug(
        `ScrapList for material ${scrapListData.materialId} is inserted`,
        context,
      );
    } catch (error) {
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'scrap-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'scrap-list',
      );
      this.customLogger.error(
        `error in insert in database: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('scrapList.u')
  private async updateScrapList(payload: ScrapList): Promise<void> {
    const context = ScrapListService.createLogContext(
      'updateScrapList',
      payload?.plant,
      payload?.scrapListId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    const startTime = Date.now();
    try {
      const { scrapListId, plant } = payload;
      const { ...scrapListData } = payload;

      const scrapListToFind = await this.scrapListRepository.findOne({
        where: { plant, scrapListId },
      });

      if (!scrapListToFind) {
        this.customLogger.error(
          `ScrapList with id ${scrapListId} and plant ${plant} not found nad will be created instead`,
          context,
        );

        this.create(payload);
      }
      scrapListData.creationDate = new Date(payload.creationDate);
      await this.scrapListRepository.update(
        { plant, scrapListId },
        scrapListData,
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'scrap-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'scrap-list',
      );

      this.customLogger.debug(
        `ScrapList for material ${scrapListData.materialId} is updated`,
        context,
      );
    } catch (error) {
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'scrap-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'scrap-list',
      );
      this.customLogger.error(
        `Error updating ScrapList: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('scrapList.r')
  private async readSnapshot(payload: ScrapList): Promise<void> {
    const context = ScrapListService.createLogContext(
      'readSnapshot',
      payload?.plant,
      payload?.scrapListId,
    );

    if (!payload) {
      return this.customLogger.error(`payload is empty${payload}`, context);
    }

    const { scrapListId, plant, ...scrapListData } = payload;

    // ✅ Convert timestamp → Date if needed
    if (
      scrapListData.creationDate &&
      typeof scrapListData.creationDate === 'number'
    ) {
      scrapListData.creationDate = new Date(scrapListData.creationDate);
    }

    const startTime = Date.now();
    try {
      await this.scrapListRepository.manager.transaction(
        async (transactionalEntityManager) => {
          let scrapListToFind = await transactionalEntityManager.findOne(
            ScrapList,
            {
              where: { plant, scrapListId },
            },
          );

          if (scrapListToFind) {
            Object.assign(scrapListToFind, scrapListData);
            this.customLogger.debug(
              `ScrapList with id ${scrapListId} and plant ${plant} is found`,
              context,
            );
          } else {
            this.customLogger.debug(
              `ScrapList with id ${scrapListId} and plant ${plant} is not found and will be inserted`,
              context,
            );
            scrapListToFind = transactionalEntityManager.create(ScrapList, {
              plant,
              scrapListId,
              ...scrapListData,
            });
          }

          await transactionalEntityManager.save(scrapListToFind);
          this.customLogger.debug(
            `Successfully upserted ScrapList with id ${scrapListId} and plant ${plant}`,
            context,
          );
        },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'scrap-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'scrap-list',
      );
    } catch {
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'scrap-list',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(payload.plant),
        'scrap-list',
      );
      this.customLogger.error(
        `Error updating ScrapList with id ${scrapListId} and plant ${plant}`,
        context,
      );
    }

    return undefined;
  }
}

